  const scaleX = useSpring(scrollYProgress, {
    stiffness: 200,
    damping: 25,
    restDelta: 0.001
  });

  // Parallax effects
  const heroTextY = useTransform(scrollYProgress, [0, 0.3], [0, 100]);

